use std::collections::{HashMap, VecDeque};

struct LruCache { cap: usize, map: HashMap<String, String>, order: VecDeque<String> }
impl LruCache {
    fn new(cap: usize) -> Self { Self { cap, map: HashMap::new(), order: VecDeque::new() } }
    fn insert(&mut self, k: String, v: String) {
        if self.map.len() >= self.cap {
            if let Some(old) = self.order.pop_front() { self.map.remove(&old); }
        }
        self.order.retain(|x| x != &k);
        self.order.push_back(k.clone());
        self.map.insert(k, v);
    }
    fn get(&self, k: &str) -> Option<&String> { self.map.get(k) }
}

