enum State { Idle, Running(u64), Paused(u64), Done }

impl State {
    fn transition(self, event: &str) -> State {
        match (self, event) {
            (State::Idle, "start") => State::Running(0),
            (State::Running(t), "pause") => State::Paused(t),
            (State::Paused(t), "resume") => State::Running(t),
            (State::Running(_), "finish") => State::Done,
            (state, _) => state,
        }
    }
}

