fn group_by<K, V, F>(items: Vec<V>, key_fn: F) -> HashMap<K, Vec<V>>
where
    K: Eq + std::hash::Hash,
    F: Fn(&V) -> K,
{
    let mut map = HashMap::new();
    for item in items {
        let k = key_fn(&item);
        map.entry(k).or_insert_with(Vec::new).push(item);
    }
    map
}

