struct EveryOther<I> { inner: I, take: bool }

impl<I: Iterator> Iterator for EveryOther<I> {
    type Item = I::Item;
    fn next(&mut self) -> Option<Self::Item> {
        while let Some(item) = self.inner.next() {
            if std::mem::replace(&mut self.take, !self.take) {
                return Some(item);
            }
        }
        None
    }
}

