enum List<T> { Nil, Cons(T, Box<List<T>>) }

impl<T> List<T> {
    fn new() -> Self { List::Nil }
    fn push(self, val: T) -> Self { List::Cons(val, Box::new(self)) }
    fn head(&self) -> Option<&T> {
        match self { List::Cons(v, _) => Some(v), List::Nil => None }
    }
}

struct Node<T> { val: T, next: Option<Box<Node<T>>> }
struct LinkedList<T> { head: Option<Box<Node<T>>> }
impl<T> LinkedList<T> {
    fn new() -> Self { LinkedList { head: None } }
    fn push(&mut self, val: T) {
        let node = Box::new(Node { val, next: self.head.take() });
        self.head = Some(node);
    }
    fn pop(&mut self) -> Option<T> {
        self.head.take().map(|node| { self.head = node.next; node.val })
    }
}

