fn quicksort(arr: &mut [i32]) {
    if arr.len() <= 1 { return; }
    let pivot_idx = partition(arr);
    quicksort(&mut arr[..pivot_idx]);
    quicksort(&mut arr[pivot_idx + 1..]);
}

fn partition(arr: &mut [i32]) -> usize {
    let pivot = arr[arr.len() - 1];
    let mut i = 0;
    for j in 0..arr.len() - 1 {
        if arr[j] <= pivot {
            arr.swap(i, j);
            i += 1;
        }
    }
    arr.swap(i, arr.len() - 1);
    i
}

fn merge_sort(arr: &mut Vec<i32>) {
    let len = arr.len();
    if len <= 1 { return; }
    let mid = len / 2;
    let mut left = arr[..mid].to_vec();
    let mut right = arr[mid..].to_vec();
    merge_sort(&mut left);
    merge_sort(&mut right);
    merge(&left, &right, arr);
}

fn merge(left: &[i32], right: &[i32], result: &mut Vec<i32>) {
    let (mut i, mut j, mut k) = (0, 0, 0);
    while i < left.len() && j < right.len() {
        if left[i] <= right[j] { result[k] = left[i]; i += 1; }
        else { result[k] = right[j]; j += 1; }
        k += 1;
    }
    while i < left.len() { result[k] = left[i]; i += 1; k += 1; }
    while j < right.len() { result[k] = right[j]; j += 1; k += 1; }
}

