    fn push(&mut self, val: T) { self.elements.push(val); }
    fn pop(&mut self) -> Option<T> { self.elements.pop() }
    fn peek(&self) -> Option<&T> { self.elements.last() }
    fn is_empty(&self) -> bool { self.elements.is_empty() }
    fn len(&self) -> usize { self.elements.len() }
}

use std::collections::VecDeque;

struct Queue<T> {
    elements: VecDeque<T>,
}

impl<T> Queue<T> {
    fn new() -> Self { Queue { elements: VecDeque::new() } }
    fn enqueue(&mut self, val: T) { self.elements.push_back(val); }
    fn dequeue(&mut self) -> Option<T> { self.elements.pop_front() }
    fn peek(&self) -> Option<&T> { self.elements.front() }
    fn is_empty(&self) -> bool { self.elements.is_empty() }
    fn len(&self) -> usize { self.elements.len() }
}

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

struct SimpleMap<K, V> {
    buckets: Vec<Vec<(K, V)>>,
    size: usize,
}

impl<K: Hash + Eq, V> SimpleMap<K, V> {
    fn new() -> Self { SimpleMap { buckets: (0..16).map(|_| Vec::new()).collect(), size: 0 } }
    fn bucket(&self, key: &K) -> usize {
        let mut h = DefaultHasher::new();
        key.hash(&mut h);
        h.finish() as usize % self.buckets.len()
    }
    fn insert(&mut self, key: K, val: V) {
        let idx = self.bucket(&key);
        self.buckets[idx].push((key, val));
        self.size += 1;
    }
    fn get(&self, key: &K) -> Option<&V> {
        let idx = self.bucket(key);
        self.buckets[idx].iter().find(|(k, _)| k == key).map(|(_, v)| v)
    }
}

use std::collections::HashMap;
use std::collections::VecDeque;

struct LruCache<K: std::hash::Hash + Eq + Clone, V> {
    capacity: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: std::hash::Hash + Eq + Clone, V> LruCache<K, V> {
    fn new(capacity: usize) -> Self {
        LruCache { capacity, map: HashMap::new(), order: VecDeque::new() }
    }
    fn get(&mut self, key: &K) -> Option<&V> {
        if self.map.contains_key(key) {
            self.order.retain(|k| k != key);
            self.order.push_back(key.clone());
            self.map.get(key)
        } else { None }
    }
    fn put(&mut self, key: K, value: V) {
        if self.map.contains_key(&key) {
            self.order.retain(|k| k != &key);
        } else if self.map.len() >= self.capacity {
            if let Some(old) = self.order.pop_front() { self.map.remove(&old); }
        }
        self.order.push_back(key.clone());
        self.map.insert(key, value);
    }
}

use std::collections::{HashMap, VecDeque};

pub struct LruCache {
    cap: usize,
    map: HashMap<String, String>,
    order: VecDeque<String>,
}

impl LruCache {
    pub fn new(cap: usize) -> Self { Self { cap, map: HashMap::new(), order: VecDeque::new() } }
    pub fn get(&mut self, key: &str) -> Option<&String> {
        if self.map.contains_key(key) {
            self.touch(key);
            self.map.get(key)
        } else { None }
    }
    fn touch(&mut self, key: &str) {
        self.order.retain(|k| k != key);
        self.order.push_back(key.to_string());
    }
}

use std::collections::HashMap;

pub struct LruCache<V> {
    capacity: usize,
    entries: HashMap<String, (V, u64)>,
    counter: u64,
}

impl<V> LruCache<V> {
    pub fn new(capacity: usize) -> Self {
        Self { capacity, entries: HashMap::new(), counter: 0 }
    }
    pub fn get(&mut self, key: &str) -> Option<&V> {
        self.counter += 1;
        let c = self.counter;
        self.entries.get_mut(key).map(|(v, ts)| { *ts = c; &*v })
    }
    pub fn put(&mut self, key: String, val: V) {
        self.counter += 1;
        if self.entries.len() >= self.capacity && !self.entries.contains_key(&key) {
            let oldest = self.entries.iter().min_by_key(|(_, (_, ts))| ts).map(|(k, _)| k.clone());
            if let Some(k) = oldest { self.entries.remove(&k); }
        }
        self.entries.insert(key, (val, self.counter));
    }
}
